from playwright.sync_api import sync_playwright
import json,hashlib
source=(ROOT/'assets/game.js').read_text();probe=r'''
window.__bounds={
 pressure:()=>{__townTest.reset('settlement',42);G.autoBuild=false;const funding=Math.min(2000000,G.region);G.region-=funding;G.treasury+=funding;const total=totalMoney(),venue=civicGatheringVenues()[0].b.id;const first=authorizeCivicGathering(reviewCivicGathering({venue,start:G.day+20}));if(!first.ok)throw Error('Pinned event');const pinned=JSON.stringify(G.civicCalendar.events[0]),samples=[];
 const industry=G.firms.find(f=>f.kind==='quarry');if(!brownfieldAssess(industry.building).ok||!brownfieldAcquire(industry.building).ok||!brownfieldFund(industry.building).ok)throw Error('Funded reserve setup');const ground=JSON.stringify(G.brownfields);for(let i=0;i<1000;i++){const q=reviewCivicGathering({venue,start:G.day+1}),r=authorizeCivicGathering(q);if(!r.ok||!cancelCivicGathering(r.id))throw Error('Calendar pressure');if(!G.civicCalendar.events.some(e=>JSON.stringify(e)===pinned)||G.civicCalendar.events.length>16)throw Error('Active event evicted');if(i%100===99)samples.push({cycle:i+1,calendar:G.civicCalendar.events.length,bytes:archivePayload().length});}
 if(JSON.stringify(G.brownfields)!==ground)throw Error('Funded ground obligation deleted');__townTest.step(25);const farm=G.firms.find(f=>f.kind==='farm'),spec={firmId:farm.id,marketId:'port',good:'grain',milestones:[{quantity:10,deadline:G.day+15},{quantity:10,deadline:G.day+30}]},firstGroup=authorizeRegionalProcurement(reviewRegionalProcurement(spec));if(!firstGroup.ok)throw Error('Pinned procurement: '+firstGroup.reason);for(let d=0;d<15&&!G.regionalTrade.shipments.some(s=>firstGroup.contractIds.includes(s.contract));d++)__townTest.step(1);cancelRegionalAgreement(firstGroup.contractIds[0]);const cargo=JSON.stringify(G.regionalTrade.shipments);if(!G.regionalTrade.shipments.some(s=>firstGroup.contractIds.includes(s.contract)))throw Error('No pinned paid cargo');
 for(let i=0;i<1000;i++){const r=authorizeRegionalProcurement(reviewRegionalProcurement(spec));if(!r.ok)throw Error(r.reason);cancelRegionalAgreement(r.contractIds[0]);if(G.regionalTrade.contracts.length>24||JSON.stringify(G.regionalTrade.shipments)!==cargo||firstGroup.contractIds.some(id=>!G.regionalTrade.contracts.some(c=>c.id===id)))throw Error('Cargo/group pruning lost obligation');if(!validateRegionalTrade(G))throw Error('Orphan group');}
 for(let i=0;i<10000;i++)migrationRecord('review',{people:0,reason:'Synthetic retention diagnostic'});if(migrationReport().length>80)throw Error('Migration recent unbounded');if(Math.abs(totalMoney()-total)>.01)throw Error('Pressure lost cash');return {calendarCycles:1000,procurementGroups:1000,calendarRows:G.civicCalendar.events.length,contractRows:G.regionalTrade.contracts.length,pinnedCargo:G.regionalTrade.shipments.length,pinnedGroupPreserved:true,migrationReviews:10000,recentRows:migrationReport().length,samples};},
 horizon:()=>{__townTest.reset('settlement',42);const total=totalMoney(),samples=[];for(let block=1;block<=20;block++){__townTest.step(720);const start=performance.now(),raw=archivePayload(),serializeMs=performance.now()-start,bytes=new Blob([raw]).size,g=G;const loadStart=performance.now();if(!hydrateSave(raw))throw Error('Year '+block*2+' rejected');const loadMs=performance.now()-loadStart;if(!validateTown().ok||Math.abs(totalMoney()-total)>.05||Math.max(...goodsBalance().map(r=>Math.abs(r.error)))>.001)throw Error('Long run books');samples.push({year:block*2,day:G.day,bytes,serializeMs,loadMs,people:G.people.length,households:G.households.length,buildings:G.buildings.length,events:G.events.length,history:G.history.length,observations:G.observations.length,transactions:G.transactions.length,brownfields:G.brownfields?.length||0,projects:G.projects.length,contracts:G.regionalTrade.contracts.length});}
 const saved=archivePayload();__townTest.step(30);const a=JSON.parse(archivePayload());if(!hydrateSave(saved))throw Error('Replay load');__townTest.step(30);const b=JSON.parse(archivePayload()),canon=v=>Array.isArray(v)?v.map(canon):v&&typeof v==='object'?Object.fromEntries(Object.keys(v).sort().map(k=>[k,canon(v[k])])):v;for(const g of[a,b]){delete g.trafficState;delete g.visualState;}if(JSON.stringify(canon(a))!==JSON.stringify(canon(b)))throw Error('Late exact replay');return {samples,lateExactReplayDays:30,cashDrift:totalMoney()-total};}
};
'''
with sync_playwright() as pw:
 b=pw.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);p=b.new_page();p.set_default_timeout(300000);p.set_content(html);p.add_script_tag(content=source.replace('// SOURCE: 99-instrumentation.js',probe+'\n// SOURCE: 99-instrumentation.js'));p.locator('#newTown').click();p.locator('#pause').click();r={'source_sha256':hashlib.sha256(source.encode()).hexdigest(),'pressure':p.evaluate('__bounds.pressure()')};print('Pressure complete',r['pressure'],flush=True);r['horizon']=p.evaluate('__bounds.horizon()');b.close()
assert hashlib.sha256((ROOT/'assets/game.js').read_bytes()).hexdigest()==r['source_sha256'];out=ROOT/'reports/history-bounds';out.mkdir(exist_ok=True);(out/'result.json').write_text(json.dumps(r,indent=2)+'\n');print('PASS',json.dumps(r['horizon']))
